 * The parser for the configuration document. It turns the text of a document
 * into a tree of nodes, or throws a ConfError naming the line and the reason.
 *
 * A node is one of
 *   { t: 'table',   map: Map, defined: boolean }
 *   { t: 'atable',  items: [table] }
 *   { t: 'array',   items: [node] }
 *   { t: 'string' | 'integer' | 'float' | 'boolean', v }
 */

export class ConfError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

const NAME_CHAR = /[A-Za-z0-9_-]/
const INTEGER = /^[+-]?[0-9]+(_[0-9]+)*$/
const FLOAT = /^[+-]?[0-9]+(_[0-9]+)*(\.[0-9]+(_[0-9]+)*)?([eE][+-]?[0-9]+(_[0-9]+)*)?$/

function newTable(defined) {
  return { t: 'table', map: new Map(), defined }
}

function joinKey(base, name) {
  return base === '' ? name : `${base}.${name}`
}

/** A cursor over one line of the document. */
class Cursor {
  constructor(text, line) {
    this.s = text
    this.i = 0
    this.line = line
  }

  fail(reason) {
    throw new ConfError(this.line, reason)
  }

  get done() {
    return this.i >= this.s.length
  }

  peek() {
    return this.i < this.s.length ? this.s[this.i] : ''
  }

  skipSpace() {
    while (this.i < this.s.length && (this.s[this.i] === ' ' || this.s[this.i] === '\t')) this.i++
  }

  /** True where the rest of the line is blank or a comment. */
  atEnd() {
    const c = this.peek()
    return c === '' || c === '#' || c === ';'
  }

  /** Spaces, tabs and a comment may follow; anything else is the given error. */
  finish(reason) {
    this.skipSpace()
    if (!this.atEnd()) this.fail(reason)
    this.i = this.s.length
  }

  parseString() {
    const quote = this.s[this.i]
    this.i++
    let out = ''
    for (;;) {
      if (this.done) this.fail('unterminated string')
      const c = this.s[this.i]
      if (c === quote) {
        this.i++
        return out
      }
      if (quote === '"' && c === '\\') {
        this.i++
        if (this.done) this.fail('unterminated string')
        const e = this.s[this.i]
        if (e === 'u') {
          const hex = this.s.slice(this.i + 1, this.i + 5)
          if (!/^[0-9a-fA-F]{4}$/.test(hex)) this.fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(hex, 16))
          this.i += 5
          continue
        }
        const simple = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (!Object.prototype.hasOwnProperty.call(simple, e)) this.fail(`invalid escape \\${e}`)
        out += simple[e]
        this.i++
        continue
      }
      out += c
      this.i++
    }
  }

  parseName() {
    const c = this.peek()
    if (c === '"' || c === "'") return this.parseString()
    const start = this.i
    while (this.i < this.s.length && NAME_CHAR.test(this.s[this.i])) this.i++
    if (this.i === start) this.fail('expected a name')
    return this.s.slice(start, this.i)
  }

  /** Names joined by dots, with spaces and tabs allowed around each dot. */
  parseDottedName() {
    this.skipSpace()
    const names = [this.parseName()]
    for (;;) {
      const mark = this.i
      this.skipSpace()
      if (this.peek() !== '.') {
        this.i = mark
        return names
      }
      this.i++
      this.skipSpace()
      names.push(this.parseName())
    }
  }

  /** The text of a bare value, read up to a space, a tab or a delimiter. */
  parseBareWord() {
    const start = this.i
    while (this.i < this.s.length && !' \t,]}'.includes(this.s[this.i])) this.i++
    return this.s.slice(start, this.i)
  }

  parseValue(path) {
    this.skipSpace()
    const c = this.peek()
    if (c === '' || c === '#' || c === ';' || c === ',' || c === ']' || c === '}') {
      this.fail('expected a value')
    }
    if (c === '"' || c === "'") return { t: 'string', v: this.parseString() }
    if (c === '[') return this.parseArray(path)
    if (c === '{') return this.parseInlineTable(path)
    const word = this.parseBareWord()
    if (word === 'true') return { t: 'boolean', v: true }
    if (word === 'false') return { t: 'boolean', v: false }
    if (INTEGER.test(word)) return { t: 'integer', v: Number(word.replace(/_/g, '')) }
    if (FLOAT.test(word)) return { t: 'float', v: Number(word.replace(/_/g, '')) }
    this.fail(`invalid value ${word}`)
  }

  parseArray(path) {
    this.i++
    const node = { t: 'array', items: [] }
    for (;;) {
      this.skipSpace()
      if (this.atEnd()) this.fail('unterminated array')
      if (this.peek() === ']') {
        this.i++
        return node
      }
      node.items.push(this.parseValue(`${path}[${node.items.length}]`))
      this.skipSpace()
      if (this.atEnd()) this.fail('unterminated array')
      const c = this.peek()
      if (c === ',') {
        this.i++
        continue
      }
      if (c === ']') {
        this.i++
        return node
      }
      this.fail('unterminated array')
    }
  }

  parseInlineTable(path) {
    this.i++
    const node = newTable(false)
    this.skipSpace()
    if (this.peek() === '}') {
      this.i++
      return node
    }
    for (;;) {
      this.skipSpace()
      if (this.atEnd()) this.fail('unterminated inline table')
      const names = this.parseDottedName()
      this.skipSpace()
      if (this.peek() !== '=') this.fail('expected = in an inline table')
      this.i++
      const value = this.parseValue(joinKey(path, names.join('.')))
      assign(node, path, names, value, this.line)
      this.skipSpace()
      if (this.atEnd()) this.fail('unterminated inline table')
      const c = this.peek()
      if (c === ',') {
        this.i++
        continue
      }
      if (c === '}') {
        this.i++
        return node
      }
      this.fail('unterminated inline table')
    }
  }
}

/** Steps into the table a dot walks through, creating it where it is absent. */
function walkInto(table, name, path, line) {
  const child = table.map.get(name)
  if (child === undefined) {
    const made = newTable(false)
    table.map.set(name, made)
    return made
  }
  if (child.t === 'table') return child
  if (child.t === 'atable' && child.items.length > 0) return child.items[child.items.length - 1]
  throw new ConfError(line, `${path} is not a table`)
}

function assign(table, basePath, names, value, line) {
  let node = table
  let path = basePath
  for (let k = 0; k < names.length - 1; k++) {
    path = joinKey(path, names[k])
    node = walkInto(node, names[k], path, line)
  }
  const last = names[names.length - 1]
  path = joinKey(path, last)
  if (node.map.has(last)) throw new ConfError(line, `key ${path} is defined twice`)
  node.map.set(last, value)
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = newTable(true)
  let current = root
  let currentPath = ''

  const header = (cursor) => {
    cursor.i++
    let isArray = false
    if (cursor.peek() === '[') {
      isArray = true
      cursor.i++
    }
    const names = cursor.parseDottedName()
    cursor.skipSpace()
    if (isArray) {
      if (cursor.peek() !== ']' || cursor.s[cursor.i + 1] !== ']') cursor.fail('unterminated table header')
      cursor.i += 2
    } else {
      if (cursor.peek() !== ']') cursor.fail('unterminated table header')
      cursor.i++
    }
    cursor.finish('trailing text after a table header')

    let node = root
    let path = ''
    for (let k = 0; k < names.length - 1; k++) {
      path = joinKey(path, names[k])
      node = walkInto(node, names[k], path, cursor.line)
    }
    const last = names[names.length - 1]
    path = joinKey(path, last)
    let child = node.map.get(last)
    if (isArray) {
      if (child === undefined) {
        child = { t: 'atable', items: [] }
        node.map.set(last, child)
      } else if (child.t !== 'atable') {
        throw new ConfError(cursor.line, `${path} is not an array of tables`)
      }
      const fresh = newTable(true)
      child.items.push(fresh)
      current = fresh
    } else {
      if (child === undefined) {
        child = newTable(true)
        node.map.set(last, child)
      } else if (child.t !== 'table') {
        throw new ConfError(cursor.line, `${path} is not a table`)
      } else if (child.defined) {
        throw new ConfError(cursor.line, `table ${path} is defined twice`)
      } else {
        child.defined = true
      }
      current = child
    }
    currentPath = path
  }

  for (let n = 0; n < lines.length; n++) {
    const cursor = new Cursor(lines[n], n + 1)
    cursor.skipSpace()
    if (cursor.atEnd()) continue
    if (cursor.peek() === '[') {
      header(cursor)
      continue
    }
    const names = cursor.parseDottedName()
    cursor.skipSpace()
    if (cursor.peek() !== '=') cursor.fail('expected key = value')
    cursor.i++
    const value = cursor.parseValue(joinKey(currentPath, names.join('.')))
    cursor.finish('trailing text after a value')
    assign(current, currentPath, names, value, cursor.line)
  }

  return root
}
