    const x = left[i].codePointAt(0)
    const y = right[i].codePointAt(0)
    if (x !== y) return x < y ? -1 : 1
  }
  return left.length - right.length
}

function sortedEntries(table) {
  return [...table.map.entries()].sort((a, b) => compareKeys(a[0], b[0]))
}

function typeOf(node) {
  if (node.t === 'atable') return 'array'
  return node.t
}

function serialise(node, depth) {
  const pad = '  '.repeat(depth + 1)
  const close = '  '.repeat(depth)
  if (node.t === 'table') {
    const entries = sortedEntries(node)
    if (entries.length === 0) return '{}'
    const body = entries.map(([key, value]) => `${pad}${JSON.stringify(key)}: ${serialise(value, depth + 1)}`)
    return `{\n${body.join(',\n')}\n${close}}`
  }
  if (node.t === 'array' || node.t === 'atable') {
    if (node.items.length === 0) return '[]'
    const body = node.items.map((item) => `${pad}${serialise(item, depth + 1)}`)
    return `[\n${body.join(',\n')}\n${close}]`
  }
  if (node.t === 'string') return JSON.stringify(node.v)
  if (node.t === 'boolean') return node.v ? 'true' : 'false'
  return JSON.stringify(node.v)
}

export function toJson(root) {
  return `${serialise(root, 0)}\n`
}

function walk(node, path, out) {
  if (node.t === 'table') {
    for (const [key, child] of sortedEntries(node)) {
      const childPath = path === '' ? key : `${path}.${key}`
      out.push(`${childPath} ${typeOf(child)}`)
      walk(child, childPath, out)
    }
    return
  }
  if (node.t === 'array' || node.t === 'atable') {
    node.items.forEach((item, index) => {
      const childPath = `${path}[${index}]`
      out.push(`${childPath} ${typeOf(item)}`)
      walk(item, childPath, out)
    })
  }
}

export function toKeys(root) {
  const out = []
  walk(root, '', out)
  return out.map((line) => `${line}\n`).join('')
}
"}

